import os
from pathlib import Path
from typing import Literal

import pandas as pd
from dotenv import load_dotenv
from openai import OpenAI
from pydantic import BaseModel, ConfigDict, Field


class Evaluation(BaseModel):
    """Evaluation of an answer generated by the Case Management Agent."""

    model_config = ConfigDict(extra="forbid")

    customer_email: str = Field(
        description="Original email sent by the customer."
    )

    automated_answer: str = Field(
        description="Automated answer generated for the customer."
    )

    quality: Literal[
        "coherent",
        "not_coherent",
    ] = Field(
        description="Coherence of the automated answer."
    )


SYSTEM_PROMPT = """
You are an Evaluation Agent for an insurance company.

You will receive:
- an email sent by a customer;
- an automated answer generated by a Case Management Agent.

Your task is to decide whether the automated answer is coherent with
the customer's request.

An answer is coherent when:
- it addresses the customer's request;
- it is relevant and clear;
- it does not contradict the customer's email;
- it is sufficiently complete and professional.

Otherwise, the answer is not coherent.
""".strip()


IMPORTANT_FEATURES = [
    "body",
    "response_email",
]


def load_data(
    input_path: Path,
) -> pd.DataFrame:
    """Load the case-management CSV and validate its columns."""

    if not input_path.exists():
        raise FileNotFoundError(
            f"Input dataset not found: {input_path}"
        )

    dataframe = pd.read_csv(
        input_path,
        dtype=str,
        keep_default_na=False,
    )

    required_columns = {
        "action",
        "body",
        "response_email",
    }

    missing_columns = required_columns - set(dataframe.columns)

    if missing_columns:
        raise ValueError(
            "The dataset is missing columns: "
            f"{sorted(missing_columns)}"
        )

    return dataframe


def filter_data(
    dataframe: pd.DataFrame,
    important_features: list[str],
) -> pd.DataFrame:
    """Select the emails that received an automated answer."""

    missing_features = (
        set(important_features) - set(dataframe.columns)
    )

    if missing_features:
        raise ValueError(
            "The dataframe is missing features: "
            f"{sorted(missing_features)}"
        )

    reply_mask = dataframe["action"] == "reply_to_client"

    filtered_dataframe = dataframe.loc[
        reply_mask,
        important_features,
    ].copy()

    non_empty_answer_mask = (
        filtered_dataframe["response_email"]
        .str.strip()
        .ne("")
    )

    return filtered_dataframe.loc[
        non_empty_answer_mask
    ]


def build_evaluation_input(
    email: pd.Series,
) -> list[dict[str, str]]:
    """Build the model input for one email and its automated answer."""

    user_prompt = """
Evaluate the following automated insurance email.

Customer email:
{body}

Automated answer:
{response_email}

Decide whether the automated answer is coherent or not coherent.
""".strip().format(**email)

    return [
        {
            "role": "system",
            "content": SYSTEM_PROMPT,
        },
        {
            "role": "user",
            "content": user_prompt,
        },
    ]


def evaluate_single_email(
    email: pd.Series,
    client: OpenAI,
    model: str,
) -> Evaluation:
    """Evaluate one automated answer using the language model."""

    model_input = build_evaluation_input(email)

    response = client.responses.parse(
        model=model,
        input=model_input,
        text_format=Evaluation,
    )

    evaluation = response.output_parsed

    if evaluation is None:
        raise RuntimeError(
            "The model did not return a valid evaluation."
        )

    return evaluation


def evaluation_agent(
    dataframe: pd.DataFrame,
    client: OpenAI,
    model: str,
) -> dict[str, int]:
    """Evaluate all automated answers and count the results."""

    coherent_count = 0
    not_coherent_count = 0
    error_count = 0

    for index, email in dataframe.iterrows():
        print(f"Evaluating answer {index}...")

        try:
            evaluation = evaluate_single_email(
                email=email,
                client=client,
                model=model,
            )

            if evaluation.quality == "coherent":
                coherent_count += 1
            else:
                not_coherent_count += 1

        except Exception as error:
            error_count += 1
            print(
                f"Answer {index} could not be evaluated: "
                f"{error}"
            )

    return {
        "total_evaluated": (
            coherent_count + not_coherent_count
        ),
        "coherent": coherent_count,
        "not_coherent": not_coherent_count,
        "errors": error_count,
    }


def main() -> None:
    """Load the data, evaluate the answers and print the results."""

    load_dotenv()

    api_key = os.getenv("OPENAI_API_KEY")

    if not api_key:
        raise ValueError(
            "OPENAI_API_KEY was not found. "
            "Check the .env file."
        )

    client = OpenAI(api_key=api_key)

    model = os.getenv(
        "OPENAI_MODEL",
        "gpt-5.4-mini",
    )

    input_path = Path(
        "data/case_decisions.csv"
    )

    dataframe = load_data(
        input_path=input_path,
    )

    filtered_dataframe = filter_data(
        dataframe=dataframe,
        important_features=IMPORTANT_FEATURES,
    )

    if filtered_dataframe.empty:
        print("There are no automated answers to evaluate.")
        return

    print(
        f"Evaluating {len(filtered_dataframe)} "
        f"automated answers..."
    )

    results = evaluation_agent(
        dataframe=filtered_dataframe,
        client=client,
        model=model,
    )

    print()
    print("Evaluation completed")
    print(f"Total evaluated: {results['total_evaluated']}")
    print(f"Coherent: {results['coherent']}")
    print(f"Not coherent: {results['not_coherent']}")
    print(f"Errors: {results['errors']}")


if __name__ == "__main__":
    main()





